package com.unique.examine.openapi.api;
import com.unique.examine.openapi.repository.*;import java.util.*;
public final class PlatformOpenApiViews {private PlatformOpenApiViews(){}
    public record Application(String id,String serviceAccountId,String appKey,String name,String status,Set<String> scopes,List<String> ipAllowlist,int rateLimitPerMinute,int credentialVersion,String secretRef,long version,String createdAt,String updatedAt){public Application{scopes=Set.copyOf(scopes);ipAllowlist=List.copyOf(ipAllowlist);}public static Application from(PlatformOpenApiRepository.ApplicationBundle b){var a=b.application();return new Application(Long.toString(a.id()),Long.toString(a.serviceAccountId()),a.appKey(),a.name(),a.status().name(),a.scopes(),a.ipAllowlist(),a.rateLimitPerMinute(),b.credential().credentialVersion(),mask(b.credential().secretRef()),a.version(),a.createdAt().toString(),a.updatedAt().toString());}private static String mask(String ref){var i=ref.indexOf(':');return i<0?"***":ref.substring(0,i+1)+"***";}}
    public record ApplicationPage(List<Application> items,int page,int size,long total){public ApplicationPage{items=List.copyOf(items);}}
    public record CallLog(String id,Integer credentialVersion,String routeTemplate,String requestMethod,String resultCategory,int httpStatus,long latencyMs,String requestId,String traceId,String observedIp,String createdAt){public static CallLog from(OpenApiRepository.ApplicationCallLog l){return new CallLog(Long.toString(l.id()),l.credentialVersion(),l.routeTemplate(),l.requestMethod(),l.resultCategory().name(),l.httpStatus(),l.latencyMs(),l.requestId(),l.traceId(),l.observedIp(),l.createdAt().toString());}}
    public record CallLogPage(List<CallLog> items,int page,int size,long total){public CallLogPage{items=List.copyOf(items);}}
}
